OUT=bundle.ROOT/'cp6-proof/t3/CP7_F05_NATIVE_ANALYSIS.json'
def public_state(cur):
 # The accepted harness aggregates functions ORDER BY 1, a constant inside
 # jsonb_agg. PostgreSQL may return unchanged pg_proc members in another physical
 # order after ACL updates. Sort every original [signature,definition_hash]
 # pair without deleting a field/member or changing the frozen case runner.
 state=native.public_state(cur)
 return canonical_public_state(state)

def verify(cur):
 bundle.verify(cur)
 payroll.verify(cur,True,True,True,True,True);finance.verify(cur);f03.journal.verify(cur);f03.misc.verify(cur);f03.installment.verify(cur)
 note_correction.verify(cur);f03.transaction_source.verify(cur);f03.misc_correction.verify(cur)
 payment_correction_ownership.verify(cur)
 return_correction_ownership.verify(cur)
 sales_chain_ownership.verify(cur)
 f03.cutting_correction.verify(cur)
 return dict(stage='EXPLICIT_F03_COMBINED_DEVELOPMENT_STACK',source_sha256=hashlib.sha256(bundle.bundle().encode()).hexdigest(),full_family_acceptance=False)

def bounded_group_names(required,transport=False,model_target=False,model_target_part=None,history_runtime=False,scoped_evaluation=False,model_target_v2_part=None,frozen_facade=False,frozen_work_transport=False):
 if frozen_work_transport:
  if not transport or frozen_facade or model_target or model_target_part is not None or history_runtime or scoped_evaluation or model_target_v2_part is not None or required!={'native':1,'races':5,'http':3}:raise ValueError('FROZEN_WORK_TRANSPORT_BUDGET_CHANGED')
  return tuple(required)
 if frozen_facade:
  if not transport or model_target or model_target_part is not None or history_runtime or scoped_evaluation or model_target_v2_part is not None or required!={'native':3,'races':3,'http':2}:raise ValueError('FROZEN_FACADE_TRANSPORT_BUDGET_CHANGED')
  return tuple(required)
 if model_target_v2_part is not None:
  from cp7_ow11_model_target_transport_v2_parts import selected
  if not transport or model_target or model_target_part is not None or history_runtime or scoped_evaluation or required!=selected(model_target_v2_part).REQUIRED:raise ValueError('MODEL_TARGET_V2_TRANSPORT_PART_BUDGET_CHANGED')
  return tuple(required)
 # New bounded suites use their exact predeclared group budget. A browser
 # extension must not inherit the predecessor's native-only total selector.
 if scoped_evaluation:
  if not transport or history_runtime or model_target or model_target_part is not None or required!={'native':1,'races':4,'http':2}:raise ValueError('MODEL_SCOPED_EVALUATION_TRANSPORT_BUDGET_CHANGED')
  return tuple(required)
 if history_runtime:
  if not transport or model_target or model_target_part is not None or required!={'native':1,'races':4,'http':2}:raise ValueError('MODEL_HISTORY_RUNTIME_TRANSPORT_BUDGET_CHANGED')
  return tuple(required)
 if model_target_part is not None:
  from cp7_ow11_model_target_transport_parts import selected
  if not transport or not model_target or required!=selected(model_target_part).REQUIRED:raise ValueError('MODEL_TARGET_TRANSPORT_PART_BUDGET_CHANGED')
  return tuple(required)
 if model_target:
  if not transport or required!={'native':1,'races':7,'http':3}:raise ValueError('MODEL_TARGET_TRANSPORT_BUDGET_CHANGED')
  return tuple(required)
 if transport:
  if required!={'native':1,'races':6,'http':3}:raise ValueError('BOUNDED_TRANSPORT_BUDGET_CHANGED')
  return tuple(required)
 if not required or not set(required)<= {'native','browser','committed'}:
  raise ValueError('BOUNDED_PREDECLARED_GROUP_CHANGED')
 return tuple(required)


